#include "intern/drw_textcodec.h"
#include <iomanip>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>

static std::string hex(std::string_view input) {
    std::ostringstream out;
    for (unsigned char byte : input)
        out << std::hex << std::setw(2) << std::setfill('0') << unsigned(byte);
    return out.str();
}

static std::string unhex(const std::string& input) {
    if (input == "-") return {};
    if (input.size() % 2u != 0u) throw std::runtime_error("odd hex");
    std::string result;
    for (std::size_t i = 0; i < input.size(); i += 2u)
        result.push_back(static_cast<char>(std::stoul(input.substr(i, 2u), nullptr, 16)));
    return result;
}

int main() {
    std::string alias, inputHex, expectedHex;
    int dxf;
    while (std::cin >> alias >> dxf >> inputHex >> expectedHex) {
        DRW_TextCodec codec;
        codec.setVersion(DRW::AC1015, dxf != 0);
        codec.setCodePage(alias, dxf != 0);
        const auto selected = codec.declaredCodePageSelection();
        const auto decoded = codec.toUtf8(unhex(inputHex));
        const auto observation = codec.lastDecodeObservation();
        const auto encodedExpected = expectedHex == "-" ? std::string{}
            : codec.fromUtf8(unhex(expectedHex));
        const auto decodedEncodedExpected = expectedHex == "-" ? std::string{}
            : codec.toUtf8(encodedExpected);
        std::cout << alias << '\t' << dxf << '\t' << inputHex << '\t'
                  << codec.getCodePage() << '\t' << unsigned(selected.kind) << '\t'
                  << hex(decoded) << '\t' << hex(encodedExpected) << '\t'
                  << hex(decodedEncodedExpected) << '\t' << observation.issues << '\n';
    }
}
